mapper.update:
UPDATE knowledge_paragraph AS t SET embedding = v.vec::vector, vector_status = 'embedded' FROM (VALUES
(#{it.id}, #{it.vector}::vector)
) AS v(id, vec) WHERE t.id = v.id

mapper.select:
SELECT id, document_id, knowledge_base_id, content, title,
       pgroonga_score(tableoid, ctid) AS rank
FROM knowledge_paragraph
WHERE deleted = 0
  AND knowledge_base_id = #{kbId}
  AND content &@~ #{query}
ORDER BY rank DESC
LIMIT #{topK}

SELECT id, document_id, knowledge_base_id, content, title, 1 - (embedding <=> #{vector}::vector) AS similarity FROM knowledge_paragraph WHERE deleted = 0 AND vector_status = 'embedded' AND document_id IN
#{d}
ORDER BY embedding <=> #{vector}::vector LIMIT #{topK}

SELECT id, document_id, knowledge_base_id, content, title
FROM knowledge_paragraph
WHERE deleted = 0
  AND id IN

    #{d}

LIMIT #{limit}
